//! The catalog of the daemon's log lines, generated by `build.rs` from the code: a log line enters
//! the report only when its fixed text is one of these, and each hole only with a safe value.
use std::collections::HashSet;
use std::sync::OnceLock;

use super::extract;

const CATALOG: &str = include_str!(concat!(env!("OUT_DIR"), "/log-catalog.txt"));
const VOCABULARY: &str = include_str!(concat!(env!("OUT_DIR"), "/vocabulary.txt"));

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Piece {
    Text(String),
    Hole(String),
}

#[derive(Debug)]
pub struct Template {
    pub origin: String,
    pub pieces: Vec<Piece>,
    fixed: usize,
}

pub struct Catalog {
    pub templates: Vec<Template>,
    pub vocabulary: HashSet<String>,
}

impl Catalog {
    pub fn built() -> &'static Catalog {
        static BUILT: OnceLock<Catalog> = OnceLock::new();
        BUILT.get_or_init(|| Catalog::parse(CATALOG, VOCABULARY))
    }

    pub fn parse(catalog: &str, vocabulary: &str) -> Catalog {
        let mut templates: Vec<Template> = catalog
            .lines()
            .filter_map(extract::parse_catalog_line)
            .map(|(origin, format)| {
                let pieces = pieces(&format);
                let fixed = pieces.iter().map(|p| if let Piece::Text(t) = p { t.len() } else { 0 }).sum();
                Template { origin: origin.to_owned(), pieces, fixed }
            })
            .filter(|template| template.pieces.iter().any(|p| matches!(p, Piece::Text(t) if t.chars().any(char::is_alphabetic))))
            .collect();
        templates.sort_by(|a, b| b.fixed.cmp(&a.fixed));
        Catalog { templates, vocabulary: vocabulary.lines().filter(|w| !w.is_empty()).map(str::to_owned).collect() }
    }

    /// The most specific template whose fixed text matches all of `message`, with the value of each
    /// hole.
    pub fn matching<'a>(&self, message: &'a str) -> Option<(&Template, Vec<&'a str>)> {
        self.templates.iter().find_map(|template| fill(&template.pieces, message).map(|values| (template, values)))
    }
}

/// A format string as fixed text and holes: `{}` and `{name:?}` are holes, `{{` is a `{`.
pub fn pieces(format: &str) -> Vec<Piece> {
    let mut out = Vec::new();
    let mut text = String::new();
    let mut chars = format.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '{' if chars.peek() == Some(&'{') => {
                chars.next();
                text.push('{');
            }
            '}' if chars.peek() == Some(&'}') => {
                chars.next();
                text.push('}');
            }
            '{' => {
                let mut name = String::new();
                for c in chars.by_ref() {
                    if c == '}' {
                        break;
                    }
                    name.push(c);
                }
                if !text.is_empty() {
                    out.push(Piece::Text(std::mem::take(&mut text)));
                }
                let name = name.split(':').next().unwrap_or_default().to_owned();
                if matches!(out.last(), Some(Piece::Hole(_))) {
                    out.pop();
                    out.push(Piece::Hole(String::new()));
                } else {
                    out.push(Piece::Hole(name));
                }
            }
            c => text.push(c),
        }
    }
    if !text.is_empty() {
        out.push(Piece::Text(text));
    }
    out
}

/// The values of the holes when the fixed text of `pieces` matches the whole of `message`; each
/// hole takes the shortest value that lets the next fixed text follow, the last one the rest.
pub fn fill<'a>(pieces: &[Piece], message: &'a str) -> Option<Vec<&'a str>> {
    let mut values = Vec::new();
    let mut at = 0;
    let mut open_hole = false;
    for (index, piece) in pieces.iter().enumerate() {
        match piece {
            Piece::Hole(_) => open_hole = true,
            Piece::Text(text) => {
                let last = index == pieces.len() - 1;
                let found = if !open_hole {
                    message[at..].starts_with(text.as_str()).then_some(at)
                } else if last {
                    (message.len() >= at + text.len() && message.ends_with(text.as_str())).then(|| message.len() - text.len())
                } else {
                    message[at..].find(text.as_str()).map(|i| at + i)
                }?;
                if open_hole {
                    let value = &message[at..found];
                    if value.is_empty() {
                        return None;
                    }
                    values.push(value);
                    open_hole = false;
                }
                at = found + text.len();
            }
        }
    }
    if open_hole {
        if at >= message.len() {
            return None;
        }
        values.push(&message[at..]);
        at = message.len();
    }
    (at == message.len()).then_some(values)
}
